window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-9501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμηχανάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 983 na letra δ · nº geral 9501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esforçar-se por; tentar todos os meios para, com inf. ou com ὅπως.</p></section></article>\n<article id=\"entry-dgp-9502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμηχανητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 984 na letra δ · nº geral 9502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διαμηχανάομαι.</p></section></article>\n<article id=\"entry-dgp-9503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμίγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 985 na letra δ · nº geral 9503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διαμιγνύω (fut. διαμίξω, part. perf. pas. fem. διαμεμιγμέναι) misturar.</p></section></article>\n<article id=\"entry-dgp-9504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμικρολογέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 986 na letra δ · nº geral 9504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3a sing. impf. διεμικρολογεῖτο) opor pequenas razões; mostrar-se impertinente contra alguém, πρός e ac.; contestar.</p></section></article>\n<article id=\"entry-dgp-9505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμιλλάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 987 na letra δ · nº geral 9505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lutar com ardor; lutar até o fim com alguém, dat. ou πρός e ac., por algo, ἐν e dat. ou περί e ac. 〈διά, ἁμιλάομαι〉</p></section></article>\n<article id=\"entry-dgp-9506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμιλλητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 988 na letra δ · nº geral 9506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διαμιλλάομαι.</p></section></article>\n<article id=\"entry-dgp-9507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμιμνῄσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 989 na letra δ · nº geral 9507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer menção de; recordar ♦ pas. (perf. διαμέμνημαι) 2 guardar a lembrança de.</p></section></article>\n<article id=\"entry-dgp-9508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμισέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 990 na letra δ · nº geral 9508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">detestar profundamente; odiar.</p></section></article>\n<article id=\"entry-dgp-9509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμιστύλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 991 na letra δ · nº geral 9509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contar em pequenos pedaços.</p></section></article>\n<article id=\"entry-dgp-9510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμνημονεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 992 na letra δ · nº geral 9510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lembrar-se bem; conservar uma lembrança de alguém, gen., de algo, ac. 2 fazer lembrar algo, ac., a alguém, dat. 3 trazer à lembrança; mencionar, ac. ou com part.: διαμνημονεύεται ἔχων xen. lembra-se de que tinha.</p></section></article>\n<article id=\"entry-dgp-9511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμοιράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 993 na letra δ · nº geral 9511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. e méd. 1 fazer em pedaços; dilacerar ♦ méd. 2 distribuir; partilhar.</p></section></article>\n<article id=\"entry-dgp-9512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμολύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 994 na letra δ · nº geral 9512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cobrir com uma nova escrita; manchar escrevendo; borrar.</p></section></article>\n<article id=\"entry-dgp-9513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμονομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 995 na letra δ · nº geral 9513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bater-se em duelo contra alguém, dat. ou πρός e ac.</p></section></article>\n<article id=\"entry-dgp-9514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμορφόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 996 na letra δ · nº geral 9514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar uma forma a; moldar, ac. 2 representar alegoricamente.</p></section></article>\n<article id=\"entry-dgp-9515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμόρφωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 997 na letra δ · nº geral 9515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de formar, de moldar. 〈διαμορφόω〉</p></section></article>\n<article id=\"entry-dgp-9516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμπάξ</h1><div class=\"entry-meta\"><span>DGP · ordem 998 na letra δ · nº geral 9516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de parte em parte; de um lado a outro: διελαύνεται δ. luc. [Arsaces] é trespassado de um lado a outro ♦ prep. 2 de um lado a outro de, através de, gen.: ἰάπτει μηλοβότου Φρυγίας δ. ésql. lança-se através da Frigia, nutriz de ovelhas. 〈διά, ἀνά, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-9517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμπερές</h1><div class=\"entry-meta\"><span>DGP · ordem 999 na letra δ · nº geral 9517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. διαμπερής.</p></section></article>\n<article id=\"entry-dgp-9518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμπερής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 1000 na letra δ · nº geral 9518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que trespassa: ὀδύνη δ. hipócr. dor aguda ♦ διαμπερές adv. 2 (lugar) de uma ponta a outra; de um lado a outro 3 (tempo) do início ao fim; sem interrupção; continuamente ♦ τὸ ∆ιαμπερές 4 a Passagem, nome de uma porta de Argos. 〈διά, ἀναπείρω〉</p></section></article>\n<article id=\"entry-dgp-9519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμυδαλέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1001 na letra δ · nº geral 9519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lágrimas que inundam o rosto. 〈διά, μυδαλέος〉</p></section></article>\n<article id=\"entry-dgp-9520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμυθολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1002 na letra δ · nº geral 9520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expressar em palavras; falar, ac. 2 en­treter-se; conversar: δ. πρὸς ἀλλήλους plat. conversar uns com os outros.</p></section></article>\n<article id=\"entry-dgp-9521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμφίδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1003 na letra δ · nº geral 9521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">totalmente diferente; muito diferente. 〈διά, ἀμφίς〉</p></section></article>\n<article id=\"entry-dgp-9522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμφισβητέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1004 na letra δ · nº geral 9522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 discordar; discutir com alguém, dat. ou πρός e ac., por causa de algo, περί e gen. ♦ pas. 2 ser objeto de discussão; ser objeto de controvérsia: τὰ διαμφισβητούμενα as questões controversas. 〈διά, ἀμφισβητέω〉</p></section></article>\n<article id=\"entry-dgp-9523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαμφισβήτησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1005 na letra δ · nº geral 9523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contestação; discussão; controvérsia. 〈διαμφισβητέω〉</p></section></article>\n<article id=\"entry-dgp-9524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαναγιγνώσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1006 na letra δ · nº geral 9524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαναγνώσομαι etc.) ler do princípio ao fim, ac. 〈διά, ἀναγιγνώσκω〉</p></section></article>\n<article id=\"entry-dgp-9525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαναπαύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1007 na letra δ · nº geral 9525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 deixar repousar por algum tempo, ac. 2 in­terromper; suspender ♦ méd. 3 repousar por algum tempo; ter algum repouso. 〈διά, ἀναπαύω〉</p></section></article>\n<article id=\"entry-dgp-9526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαναυμαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1008 na letra δ · nº geral 9526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer um combate naval; lutar no mar.</p></section></article>\n<article id=\"entry-dgp-9527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανάω</h1><div class=\"entry-meta\"><span>DGP · ordem 1009 na letra δ · nº geral 9527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">manar; jorrar.</p></section></article>\n<article id=\"entry-dgp-9528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάνδιχα</h1><div class=\"entry-meta\"><span>DGP · ordem 1010 na letra δ · nº geral 9528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em duas partes; em dois: δ. μερμήριζεν hom. estava dividido entre duas opiniões 2 pela metade: σοὶ δὲ δ. δῶκε hom. ele te deu [dons] pela metade. 〈διά, ἄνδιχα〉</p></section></article>\n<article id=\"entry-dgp-9529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανέμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1011 na letra δ · nº geral 9529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">partilha; distribuição. 〈διανέμω〉</p></section></article>\n<article id=\"entry-dgp-9530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανεμητέον</h1><div class=\"entry-meta\"><span>DGP · ordem 1012 na letra δ · nº geral 9530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διανέμω.</p></section></article>\n<article id=\"entry-dgp-9531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δανεμητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1013 na letra δ · nº geral 9531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que reparte; que distribui; distributivo de, gen. 2 que se pode dividir; divisível. 〈δια­νέμω〉</p></section></article>\n<article id=\"entry-dgp-9532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανεμόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1014 na letra δ · nº geral 9532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só perf. pas.) ser agitado ou levado pelo vento; flutuar ao sabor do vento. 〈διά, ἀνεμόω〉</p></section></article>\n<article id=\"entry-dgp-9533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 1015 na letra δ · nº geral 9533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διανεμῶ etc.) 1 distribuir; partilhar; dividir algo, ac., com alguém, dat. 2 administrar; governar ♦ méd. 3 partilhar entre si 4 dividir.</p></section></article>\n<article id=\"entry-dgp-9534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανέστην</h1><div class=\"entry-meta\"><span>DGP · ordem 1016 na letra δ · nº geral 9534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor.2 méd. intr. de διανίστημι.</p></section></article>\n<article id=\"entry-dgp-9535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1017 na letra δ · nº geral 9535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer sinais de cabeça em diversas direções; fazer sinais com a cabeça; acenar 2 desviar a cabeça; desviar-se de algo, ac.</p></section></article>\n<article id=\"entry-dgp-9536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανέω</h1><div class=\"entry-meta\"><span>DGP · ordem 1018 na letra δ · nº geral 9536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διανεύσομαι etc.) 1 atravessar a nado; cruzar a nado, ac. 2 ultrapassar; superar (situações).</p></section></article>\n<article id=\"entry-dgp-9537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανήχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1019 na letra δ · nº geral 9537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atravessar a nado 2 lutar a nado 3 (som) atravessar; ultrapassar.</p></section></article>\n<article id=\"entry-dgp-9538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1020 na letra δ · nº geral 9538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(perf. pas. διήνθισμαι) 1 ornar com flores 2 or­nar com flores bordadas 3 bordar ♦ méd. 4 colher flores para si. 〈διά, ἀνθίζω〉</p></section></article>\n<article id=\"entry-dgp-9539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανιάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1021 na letra δ · nº geral 9539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">afligir-se profundamente. 〈διά, ἀνιάω〉</p></section></article>\n<article id=\"entry-dgp-9540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανίστημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1022 na letra δ · nº geral 9540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαναστήσω; etc.) 1 fazer levantar; estimular; incitar 2 levantar; elevar ♦ méd. 3 levantar-se 4 separar-se; dividir-se em facções. 〈διά, ἀνίστημι〉</p></section></article>\n<article id=\"entry-dgp-9541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανοέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1023 na letra δ · nº geral 9541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διανοήσομαι, aor. διενοήθην, perf. διανενόημαι) 1 ter em mente; conceber; projetar, ac. ou inf.: τὰ διανοηθέντα planos, projetos 2 pensar; meditar; refletir sobre algo, περί ou ὑπέρ e gen.: λέγω νοῦν ᾧ διανοεῖται ἡ ψυχή artt. chamo mente aquilo com que a alma pensa 3 pensar; refletir; atentar em, com ὡς e part.: διανοεῖσθαι ὡς διαλλαγησομένων plat. pensar que se reconciliarão 4 estar em dada disposição de espírito, com adv.: ὁ κακῶς διανοηθεὶς περὶ τῶν οἰκείων isócr. aquele que está mal disposto para os próprios negócios 5 tard. fazer reflexões; arrepender-se.</p></section></article>\n<article id=\"entry-dgp-9542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανόημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1024 na letra δ · nº geral 9542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pensamento; idéia; noção; conceito 2 significado de palavra 3 imaginação; idéia falsa. 〈διανοέομαι〉</p></section></article>\n<article id=\"entry-dgp-9543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανόησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1025 na letra δ · nº geral 9543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 faculdade de pensar; intelecção 2 modo de pensar; opinião. 〈διανοέομαι〉</p></section></article>\n<article id=\"entry-dgp-9544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανοητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 1026 na letra δ · nº geral 9544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 referente ao pensamento; intelectual 2 engenhoso. 〈διανοέομαι〉</p></section></article>\n<article id=\"entry-dgp-9545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάνοια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1027 na letra δ · nº geral 9545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inteligência; faculdade de refletir, de raciocinar; reflexão: ὁ ἐντὸς τῆς ψυχῆς πρὸς αὐτὴν διάλογος ἐπωνομάσθη διάνοια plat. o diálogo interior da alma consigo mesma foi chamado de reflexão 2 exercício da reflexão; reflexão: ταῖς γε διανοίαις ἀποβλέψαντ᾽ εἰς τὰς συμφορὰς αὐτῶν ésqn. ficai atentos ao menos em pensamento às desgraças deles 3 disposição; intenção; desígnio; projeto: ὤλοντ᾽ ἀσεβεῖ διανοίᾳ ésql. pereceram por seu desígnio ímpio 4 previdência; precaução 5 noção; conceito; significado: τὴν Ὁμήρου διάνοιαν ἐκμανθάνειν, μὴ μόνον τὰ ἔπη ζηλωτόν ἐστι plat. saber o sentido do texto de Homero e não apenas as palavras é algo digno de inveja. 〈διά, νόος〉</p></section></article>\n<article id=\"entry-dgp-9546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανοίγω</h1><div class=\"entry-meta\"><span>DGP · ordem 1028 na letra δ · nº geral 9546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διήνοιξα etc.) 1 abrir 2 abrir para estabelecer comunicação 3 revelar; explicar (texto) ♦ méd. 4 abrir-se. 〈διά, ἀνοίγω〉</p></section></article>\n<article id=\"entry-dgp-9547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανομεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1029 na letra δ · nº geral 9547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">distribuidor. 〈διανέμω〉</p></section></article>\n<article id=\"entry-dgp-9548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανομή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1030 na letra δ · nº geral 9548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distribuição; partilha; divisão 2 direção 3 norma; regra. 〈διανέμω〉</p></section></article>\n<article id=\"entry-dgp-9549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανταῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 1031 na letra δ · nº geral 9549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 que se estende através 2 que atravessa de lado a lado; penetrante; pungente (dor) 3 que não se deixa desviar; inflexível (destino).</p></section></article>\n<article id=\"entry-dgp-9550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαντλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1032 na letra δ · nº geral 9550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exaurir 2 suportar até o fim. 〈διά, ἀνθλέω〉</p></section></article>\n<article id=\"entry-dgp-9551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανυκτερεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1033 na letra δ · nº geral 9551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar a noite; fazer vigília.</p></section></article>\n<article id=\"entry-dgp-9552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διανύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1034 na letra δ · nº geral 9552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διήνυσα) 1 levar a termo; completar; terminar 2 percorrer até o fim 3 continuar até o fim, part.: σε μυρίοις πόνοις διδοῦσα δεῦρ᾽ ἀεὶ διήνυσεν eur. ela até agora não cessou de submeter-te a infinitas provações. 〈διά, ἀνύω〉</p></section></article>\n<article id=\"entry-dgp-9553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαξαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1035 na letra δ · nº geral 9553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διέξηνα) 1 cardar 2 bater 3 estirar; dilacerar 4 dividir; separar.</p></section></article>\n<article id=\"entry-dgp-9554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαξιφισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1036 na letra δ · nº geral 9554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate com a espada. 〈διά, ξιφίζομαι〉</p></section></article>\n<article id=\"entry-dgp-9555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαξυράομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1037 na letra δ · nº geral 9555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barbear-se.</p></section></article>\n<article id=\"entry-dgp-9556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαγκρατιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1038 na letra δ · nº geral 9556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3a sing. aor. ind. διεπαγκρατίασεν) lutar com os punhos; lutar no pancrácio.</p></section></article>\n<article id=\"entry-dgp-9557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαιδαγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1039 na letra δ · nº geral 9557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 orientar a educação das crianças 2 ser mestre de 3 conduzir.</p></section></article>\n<article id=\"entry-dgp-9558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαιδεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1040 na letra δ · nº geral 9558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">passar pela escola: διαπαιδευθείς xen. tendo completado sua educação.</p></section></article>\n<article id=\"entry-dgp-9559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1041 na letra δ · nº geral 9559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer troça de ou imitar por brincadeira.</p></section></article>\n<article id=\"entry-dgp-9560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1042 na letra δ · nº geral 9560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">luta enérgica, valorosa, obstinada.</p></section></article>\n<article id=\"entry-dgp-9561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπάλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 1043 na letra δ · nº geral 9561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitar para sortear 2 destinar por sorteio.</p></section></article>\n<article id=\"entry-dgp-9562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαννυχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1044 na letra δ · nº geral 9562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διεπαννύχιζον) passar a noite inteira.</p></section></article>\n<article id=\"entry-dgp-9563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαπταίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1045 na letra δ · nº geral 9563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διεπάπταινεν) olhar ao redor, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-9564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαρατριβή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1046 na letra δ · nº geral 9564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crist. discussão violenta.</p></section></article>\n<article id=\"entry-dgp-9565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαρείς</h1><div class=\"entry-meta\"><span>DGP · ordem 1047 na letra δ · nº geral 9565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. pas. de διαπείρω.</p></section></article>\n<article id=\"entry-dgp-9566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαρθενεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1048 na letra δ · nº geral 9566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deflorar uma virgem.</p></section></article>\n<article id=\"entry-dgp-9567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάπασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1049 na letra δ · nº geral 9567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pó perfumado para o rosto ou para a pele. 〈διαπάσσω〉</p></section></article>\n<article id=\"entry-dgp-9568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπασσαλεύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1050 na letra δ · nº geral 9568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. διαπατταλεύω 1 pregar alguém com os membros afastados; crucificar 2 pregar uma pele estendida para curtir.</p></section></article>\n<article id=\"entry-dgp-9569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1051 na letra δ · nº geral 9569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. -άττω (fut. διαπάσω etc.) espargir; polvilhar; borrifar algo, gen., em, εἰς e ac.: ἐς τὰς τρίχας τῆς κεφαλῆς διαπάσας τοῦ ψήγματος her. tendo espargido pó sobre os cabelos.</p></section></article>\n<article id=\"entry-dgp-9570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπασῶν (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1052 na letra δ · nº geral 9570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἡ διὰ πασῶν χορδῶν συμφωνία oitava, acorde obtido com todas as cordas: τὸ δὶς διαπασῶν plut. a dupla oitava. 〈διά, πᾶς〉</p></section></article>\n<article id=\"entry-dgp-9571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπαύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1053 na letra δ · nº geral 9571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer cessar; pôr um fim em, ac. 2 destruir ♦ méd. 3 fazer uma pausa; interromper por algum tempo; repousar.</p></section></article>\n<article id=\"entry-dgp-9572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπειλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1054 na letra δ · nº geral 9572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ameaçar fortemente, com ὡς e fut. ind. ou inf. fut. ♦ méd. 2 proibir com ameaça, ac. ou inf. 3 dirigir ameaças violentas a alguém, dat. 〈διά, ἀπειλέω〉</p></section></article>\n<article id=\"entry-dgp-9573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάπειρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1055 na letra δ · nº geral 9573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">prova; experiência, gen.; δ. ποιεῖσθαι; λαμβάνειν pôr à prova: διάπειραν ὑμῶν λαμβάνειν βουλόμενος dem. querendo submeter-vos à prova. 〈διά, πεῖρα〉</p></section></article>\n<article id=\"entry-dgp-9574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπειράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1056 na letra δ · nº geral 9574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 provar; tentar: διαπειρῶν ταῖς δωροδο­κίαις plut. tentando corromper ♦ méd. διαπειρῶμαι (aor. διεπειράθην, perf. διαπεπείραμαι) 2 pôr à prova; provar alguém, gen. 3 provar; experimentar (alimento) 4 apurar os limites; provar; sondar 5 tentar; experimentar, inf.</p></section></article>\n<article id=\"entry-dgp-9575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1057 na letra δ · nº geral 9575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer passar totalmente através 2 transpassar.</p></section></article>\n<article id=\"entry-dgp-9576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπέμπω</h1><div class=\"entry-meta\"><span>DGP · ordem 1058 na letra δ · nº geral 9576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enviar em todas as direções 2 enviar como intermediário uma pessoa, ac., a outra, dat. ou πρός e ac. ♦ méd. 3 enviar; transmitir.</p></section></article>\n<article id=\"entry-dgp-9577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπενθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1059 na letra δ · nº geral 9577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3a plur. aor. διεπένθησαν) manter o luto.</p></section></article>\n<article id=\"entry-dgp-9578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπέντε</h1><div class=\"entry-meta\"><span>DGP · ordem 1060 na letra δ · nº geral 9578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διὰ πεντε (ἡ) = ἡ διὰ πέντε χορδῶν συμφωνία a quinta, acorde que aparece no intervalo de cinco cordas.</p></section></article>\n<article id=\"entry-dgp-9579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπεπονημένως</h1><div class=\"entry-meta\"><span>DGP · ordem 1061 na letra δ · nº geral 9579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com muito cuidado; com muito trabalho. 〈διαπονέω〉</p></section></article>\n<article id=\"entry-dgp-9580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπεραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1062 na letra δ · nº geral 9580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 levar a cabo; acabar; terminar 2 expor; contar até o fim.</p></section></article>\n<article id=\"entry-dgp-9581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπεραιόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1063 na letra δ · nº geral 9581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tirar; extrair 2 transportar 3 atravessar.</p></section></article>\n<article id=\"entry-dgp-9582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπεράω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1064 na letra δ · nº geral 9582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαπεράσω etc.) 1 passar através; atravessar; cruzar: διαπερᾶν εἰς Ἰταλίαν artt. fazer a travessia para a Itália por mar, διαπερᾶν τὸν βίον xen. passar a vida 2 traspassar; perfurar 3 reinar sobre, ac.: δ. Μολοσσίαν eur. reinar sobre a Molóssia 4 penetrar até o fim; conhecer a fundo, por experiência: οἶσθα διαπερῶν ésql. conheces a fundo 5 transportar para o outro lado.</p></section></article>\n<article id=\"entry-dgp-9583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπέρθω</h1><div class=\"entry-meta\"><span>DGP · ordem 1065 na letra δ · nº geral 9583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέπραθον, inf. ép. διαπραθέειν) devastar; assolar; arruinar.</p></section></article>\n<article id=\"entry-dgp-9584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπέτομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1066 na letra δ · nº geral 9584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέπτην) 1 voar através; passar voando; voar 2 voar; difundir-se; (notícia) espalhar-se 3 desaparecer; dissipar-se; evaporar-se.</p></section></article>\n<article id=\"entry-dgp-9585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπεύθομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1067 na letra δ · nº geral 9585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres. διαπευθόμενος) poét. = διαπυνθάνομαι.</p></section></article>\n<article id=\"entry-dgp-9586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπήγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 1068 na letra δ · nº geral 9586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enterrar através 2 tornar compacto, sólido; congelar ♦ méd. 3 ajustar fixando.</p></section></article>\n<article id=\"entry-dgp-9587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπηδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1069 na letra δ · nº geral 9587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saltar; precipitar-se com um salto 2 ultrapassar com um salto, ac. 3 penetrar rapidamente.</p></section></article>\n<article id=\"entry-dgp-9588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1070 na letra δ · nº geral 9588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. pas. fem. pl. διαπιανθεῖσαι) fazer engordar.</p></section></article>\n<article id=\"entry-dgp-9589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπιέζω</h1><div class=\"entry-meta\"><span>DGP · ordem 1071 na letra δ · nº geral 9589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. διεπίεσα) apertar junto; esmagar.</p></section></article>\n<article id=\"entry-dgp-9590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπικραίνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 1072 na letra δ · nº geral 9590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) ser amargo, duro, áspero com alguém, πρός e ac. 〈διά, πικρός〉</p></section></article>\n<article id=\"entry-dgp-9591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπίμπλημι</h1><div class=\"entry-meta\"><span>DGP · ordem 1073 na letra δ · nº geral 9591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. διεπλήσθην) 1 encher; preencher ♦ pas. 2 encher-se; saciar-se 3 estar cansado de alguém, gen.</p></section></article>\n<article id=\"entry-dgp-9592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1074 na letra δ · nº geral 9592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 beber em disputa; disputar quem bebe mais 2 brindar 3 beber no intervalo ♦ méd. 4 fazer concurso de quem bebe mais ♦ pas. 5 ser bebido num só trago.</p></section></article>\n<article id=\"entry-dgp-9593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπιπράσκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1075 na letra δ · nº geral 9593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres.) vender a preço muito baixo; liquidar.</p></section></article>\n<article id=\"entry-dgp-9594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1076 na letra δ · nº geral 9594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διέπεσον, aor.1 διέπεσα) 1 cair daqui e de lá; dispersar-se em, dat. 2 desagregar-se; dissolver-se 3 espalhar-se em todas as direções, εἰς e ac. 4 cair através; precipitar-se para alguém, πρός e ac. 5 escapar para algum lugar, εἰς e ac. 6 (tempo) escoar; transcorrer 7 enganar-se; falhar; fracassar em, gen.</p></section></article>\n<article id=\"entry-dgp-9595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπιστεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 1077 na letra δ · nº geral 9595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 confiar algo, ac., a alguém, dat. 2 ter confiança; fiar-se em alguém, dat., por alguma coisa, περί e gen. ou ac.</p></section></article>\n<article id=\"entry-dgp-9596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπλανάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 1078 na letra δ · nº geral 9596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 induzir em erro; extraviar ♦ méd. pas. 2 extraviar-se; errar.</p></section></article>\n<article id=\"entry-dgp-9597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπλασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1079 na letra δ · nº geral 9597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de dar forma; formação. 〈διαπλάσσω〉</p></section></article>\n<article id=\"entry-dgp-9598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπλάσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 1080 na letra δ · nº geral 9598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. -άττω (fut. διαπλάσω etc.) 1 moldar; modelar 2 revestir; envernizar 3 Medic. recolocar no lugar (fratura).</p></section></article>\n<article id=\"entry-dgp-9599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπλατύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 1081 na letra δ · nº geral 9599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dilatar; alargar 2 fazer engordar.</p></section></article>\n<article id=\"entry-dgp-9600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαπλέκω</h1><div class=\"entry-meta\"><span>DGP · ordem 1082 na letra δ · nº geral 9600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trançar; entrelaçar 2 tecer até o fim (a vida): δ. τὸν βίον εὖ her. concluir bem a trama da vida, διαπλέκειν arr. passar a vida 3 compor (canto) 4 desfazer o entrelaçamento; separar; desunir: δ. τὸν στρατόν plut. desorganizar o exército ♦ méd. 5 trançar para si; trançar sobre si; fazer tranças.</p></section></article>\n";
